// Общие шаги для тестов открытия переписки (#bb6e6d). Только чтение: не печатать, не отправлять, кнопки шапки не нажимать.
import { expect, Page } from '@playwright/test';

export const CONVERSATION_ID = 'a5002a64-d87f-4434-9974-731aaf9fd5c0';
export const CONVERSATION_URL = `/messages?conversation=${CONVERSATION_ID}&business=c676c730-194b-4bb7-a21b-f84ecbde34c2`;
export const CONVERSATION_TITLE = 'קיוסק פעיל ורווחי';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
/** Загрузка переписки/списка на проде под параллельной нагрузкой бывает 10+ с. */
export const LOAD = { timeout: 20_000 };

/** Блок записи на проде: все не-GET/HEAD/OPTIONS запросы отклоняются. Вызывать до первого перехода. */
export async function blockWrites(page: Page) {
  await page.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
}

export const messageInput = (page: Page) => page.getByPlaceholder('כתוב הודעה...');
/** Заголовок меню «אזור אישי» (h2 в боковом меню личного кабинета). */
export const personalAreaHeading = (page: Page) => page.getByText('אזור אישי', { exact: true });
/** Отметка времени сообщения «дд.мм.гг чч:мм» — последняя = последнее сообщение переписки. */
export const lastMessageTime = (page: Page) => page.getByText(/^\d{2}\.\d{2}\.\d{2} \d{2}:\d{2}$/).last();

const heightOf = (page: Page, text: string) =>
  page.getByText(text, { exact: true }).evaluate((el) => el.getBoundingClientRect().height);

/** Мобайл: открытая переписка занимает экран — поле ввода целиком видно, scrollY 0, меню скрыто, последнее сообщение видно. */
export async function expectConversationFillsMobileScreen(page: Page) {
  const input = messageInput(page);
  await expect(input).toBeVisible(LOAD);
  await expect(input, 'поле «כתוב הודעה...» целиком в экране').toBeInViewport({ ratio: 1 });
  await expect.poll(() => page.evaluate(() => window.scrollY), { message: 'scrollY = 0' }).toBe(0);
  await expect(personalAreaHeading(page), 'меню «אזור אישי» скрыто').toBeHidden();
  await expect.poll(() => heightOf(page, 'אזור אישי'), { message: 'высота «אזור אישי» = 0' }).toBe(0);
  await expect(lastMessageTime(page), 'последнее сообщение видно').toBeInViewport(LOAD);
}

/** Мобайл (#c5ed06): /messages без conversation — список переписок в первом экране, меню «אזור אישי» ниже списка. */
export async function expectListFirstOnMobile(page: Page) {
  await page.waitForURL((url) => url.pathname === '/messages' && !url.searchParams.has('conversation'), LOAD);
  const row = page.getByRole('heading', { name: CONVERSATION_TITLE });
  await expect(row, 'строка переписки целиком в первом экране').toBeInViewport({ ratio: 1, ...LOAD });
  await expect.poll(() => page.evaluate(() => window.scrollY), { message: 'scrollY = 0' }).toBe(0);
  await expect(page.getByPlaceholder('חפש שיחות...'), 'поиск по перепискам в экране').toBeInViewport();
  await expect(page.getByRole('heading', { name: 'שיחות', exact: true })).toBeInViewport();
  const menu = personalAreaHeading(page);
  await expect(menu, 'меню «אזור אישי» есть на странице').toBeAttached();
  const menuBox = await menu.boundingBox();
  const rowBox = await row.boundingBox();
  expect(menuBox, 'меню отрисовано').not.toBeNull();
  expect(menuBox!.y, 'меню «אזור אישי» ниже строки списка').toBeGreaterThan(rowBox!.y + rowBox!.height);
}

/** Иконка чата (облачко) в мобильной шапке — ссылка на /messages. */
export const headerChatIcon = (page: Page) => page.locator('header a[href="/messages"]:visible');
/** Колокольчик в шапке (кнопка с иконкой bell, без подписи). */
export const headerBell = (page: Page) => page.locator('header button:visible').filter({ has: page.locator('svg.lucide-bell') });
/** Гамбургер в мобильной шапке (кнопка с иконкой menu, без подписи). */
export const headerBurger = (page: Page) => page.locator('header button:visible').filter({ has: page.locator('svg.lucide-menu') });
